    //  no simd       27       79        0
    fn bulk_expansion(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0().yx() * Simd32x2::from([-1.0, 1.0]);
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g3_w = other[e321] * -1.0;
        let right_dual_g6 = other.group5().with_w(other[e45]) * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        let right_dual_g8 = other.group4() * Simd32x3::from(-1.0);
        let right_dual_g9 = other.group1().wxyz() * Simd32x4::from([-1.0, 1.0, 1.0, 1.0]);
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([
                0.0,
                (right_dual_g9[1] * self[e1]) + (right_dual_g9[2] * self[e2]) + (right_dual_g9[3] * self[e3]) - (right_dual_g3_w * self[e321]),
            ]),
            // e1, e2, e3, e4
            (self.group0().yzw() * right_dual_g0.xx().with_z(right_dual_g0[0])).with_w(0.0),
            // e5
            0.0,
            // e41, e42, e43, e45
            (right_dual_g1.www() * self.group0().yzw() * Simd32x3::from(-1.0)).with_w(0.0),
            // e15, e25, e35
            Simd32x3::from(other[e3215]) * self.group0().yzw(),
            // e23, e31, e12
            (right_dual_g1.zxy() * self.group0().zwy()) - (right_dual_g1.yzx() * self.group0().wyz()),
            // e415, e425, e435, e321
            (Simd32x3::from(right_dual_g3_w) * self.group0().yzw() * Simd32x3::from(-1.0))
                .with_w((right_dual_g0[0] * self[e321]) - (self[e1] * other[e415]) - (self[e2] * other[e425]) - (self[e3] * other[e435])),
            // e423, e431, e412
            (other.group7().yzx() * self.group0().wyz()) - (other.group7().zxy() * self.group0().zwy()),
            // e235, e315, e125
            (other.group8().zxy() * self.group0().zwy()) - (other.group8().yzx() * self.group0().wyz()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([(right_dual_g7[1] * self[e2]) + (right_dual_g7[2] * self[e3]), 0.0, 0.0, 0.0])
                + (Simd32x4::from([right_dual_g7[0], right_dual_g6[1], right_dual_g6[2], right_dual_g6[0]]) * self.group0().ywyz())
                - (Simd32x4::from([right_dual_g1[3], right_dual_g6[2], right_dual_g6[0], right_dual_g6[1]]) * self.group0().xzwy()),
            // e3215
            (self[e321] * other[e3215]) - (right_dual_g8[0] * self[e1]) - (right_dual_g8[1] * self[e2]) - (right_dual_g8[2] * self[e3]),
        );
    }
