impl BulkExpansion<Motor> for DipoleInversionOnOrigin {
    type Output = DipoleInversionOnOrigin;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        4        8        0
    //    simd4        2        5        0
    // Totals...
    // yes simd        6       13        0
    //  no simd       12       28        0
    fn bulk_expansion(self, other: Motor) -> Self::Output {
        use crate::elements::*;
        let right_dual_g0 = other.group0() * Simd32x4::from([1.0, 1.0, 1.0, -1.0]);
        let right_dual_g1 = other.group1() * Simd32x4::from([1.0, 1.0, 1.0, -1.0]);
        return DipoleInversionOnOrigin::from_groups(
            // e41, e42, e43, e45
            Simd32x4::from(right_dual_g0[3]) * self.group0(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                -(right_dual_g0[1] * self[e42]) - (right_dual_g0[2] * self[e43]),
                (right_dual_g0[3] * self[e4235]) + (right_dual_g1[2] * self[e42]),
                (right_dual_g0[3] * self[e4315]) + (right_dual_g1[0] * self[e43]),
                (right_dual_g0[3] * self[e4125]) + (right_dual_g1[1] * self[e41]),
            ]) + (Simd32x4::from([self[e1234], self[e45], self[e45], self[e45]]) * right_dual_g0.wxyz())
                - (Simd32x4::from([right_dual_g0[0], right_dual_g1[1], self[e41], self[e42]]) * self.group0().xz().with_zw(right_dual_g1[2], right_dual_g1[0])),
        );
    }
}
