impl BulkExpansion<MultiVector> for Infinity {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div
    //      f32        0       10        0
    //    simd2        0        1        0
    //    simd3        0        5        0
    //    simd4        0        3        0
    // Totals...
    // yes simd        0       19        0
    //  no simd        0       39        0
    fn bulk_expansion(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let right_dual_g1 = other.group9().yzwx() * Simd32x4::from([-1.0, -1.0, -1.0, 1.0]);
        let right_dual_g7 = other.group3().xyz() * Simd32x3::from(-1.0);
        return MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([1.0, other.group1().wxyz()[0] * self[e5] * -1.0]) * Simd32x2::from([0.0, 1.0]),
            // e1, e2, e3, e4
            Simd32x4::from(0.0),
            // e5
            other.group0().yx()[0] * self[e5] * -1.0,
            // e41, e42, e43, e45
            Simd32x3::from(0.0).with_w(right_dual_g1[3] * self[e5]) * Simd32x4::from([0.0, 0.0, 0.0, -1.0]),
            // e15, e25, e35
            Simd32x3::from(self[e5]) * right_dual_g1.xyz() * Simd32x3::from(-1.0),
            // e23, e31, e12
            Simd32x3::from(0.0),
            // e415, e425, e435, e321
            (Simd32x3::from(self[e5]) * other.group7()).with_w(0.0),
            // e423, e431, e412
            Simd32x3::from(0.0),
            // e235, e315, e125
            Simd32x3::from(self[e5]) * other.group6().xyz(),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([0.0, right_dual_g7[0] * self[e5], right_dual_g7[1] * self[e5], right_dual_g7[2] * self[e5]]) * Simd32x4::from([0.0, -1.0, -1.0, -1.0]),
            // e3215
            self[e5] * other[e45] * -1.0,
        );
    }
}
